import json, glob, collections, os, time
tot=collections.Counter()
today=time.time()-20*3600
files=[f for f in glob.glob("logs/*.jsonl") if os.path.getmtime(f)>today and ("eval_" in f or "mytest" in f) and "gemini" not in f and "standin" not in f and "r2_cmp" not in f]
for f in files:
    model={}
    for l in open(f,encoding="utf-8"):
        e=json.loads(l)
        if e["event"]=="send": model[(e["req"],e["step"])]=e["model"]
        if e["event"]=="last_token":
            m=model.get((e["req"],e["step"]),"?")
            tot[m]+=e["prompt_tokens"]+e["completion_tokens"]
for f in glob.glob("logs/groq_probe2_*.jsonl"):
    for l in open(f,encoding="utf-8"):
        e=json.loads(l)
        if e.get("usage"): tot[e["model"]]+=e["usage"]["total_tokens"]
print(files)
print(dict(tot))
E

