import json, collections, numpy as np
def look(tag):
    ev=[json.loads(l) for l in open(f"logs/server_{tag}.jsonl",encoding="utf-8")]
    t_enq={e["req"]:e["t"] for e in ev if e["event"]=="enqueue"}
    out=[]
    sent=collections.defaultdict(list)
    for e in ev:
        if e["event"]=="send": sent[e["req"]].append(e["step"])
    for e in ev:
        if e["event"]=="done" and e["status"].startswith("extractive"):
            out.append(((e["t"]-t_enq[e["req"]])*1000, e["status"], e["level"], tuple(sent[e["req"]])))
    ms=np.array([o[0] for o in out])
    print(tag,"n extractive",len(out),"median ms %.0f"%np.median(ms),"p90 %.0f"%np.percentile(ms,90))
    c=collections.Counter((o[1],o[2],o[3]) for o in out)
    for k,v in c.most_common(6): print("   ",v,k)
for t in ("s_daily_known","r2_daily_known"): look(t)
